from abc import ABC, abstractmethod


class Shape(ABC):
    @abstractmethod
    def area(self):
        """Every shape must implement this."""


class Square(Shape):
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side ** 2


class Triangle(Shape):
    def __init__(self, base, height):
        self.base = base
        self.height = height

    def area(self):
        return 0.5 * self.base * self.height


try:
    Shape()
except TypeError:
    print("Cannot instantiate abstract class Shape")

print("Square  :", Square(4).area())
print("Triangle:", Triangle(6, 3).area())

class InvalidAgeError(Exception):
    pass


def check_age(text):
    age = int(text)                      # may raise ValueError
    if age < 0 or age > 120:
        raise InvalidAgeError(f"{age} is not a realistic age")
    return age


for line in ["25", "abc", "-4", "130"]:
    try:
        print("Valid age:", check_age(line))
    except ValueError:
        print(f"'{line}' is not a number")
    except InvalidAgeError as error:
        print("Error:", error)
    finally:
        print("Done")

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None


class LinkedList:
    def __init__(self):
        self.head = None

    def add_at_end(self, value):
        new = Node(value)
        if self.head is None:
            self.head = new
            return
        cur = self.head
        while cur.next:
            cur = cur.next
        cur.next = new

    def delete(self, value):
        cur, prev = self.head, None
        while cur:
            if cur.data == value:
                if prev:
                    prev.next = cur.next
                else:
                    self.head = cur.next
                return True
            prev, cur = cur, cur.next
        return False

    def display(self):
        items, cur = [], self.head
        while cur:
            items.append(str(cur.data))
            cur = cur.next
        print(" -> ".join(items))


ll = LinkedList()
for v in [10, 20, 30, 40]:
    ll.add_at_end(v)
ll.delete(20)
ll.display()

